import { AccountingCategory, CustomerRecord, DigitalPlatformId, DigitalStatus, DirectorLink, NextBestProductRecommendation, ProductHoldingRow, ReportingMonth } from "../types/banking";

const MONTHS: ReportingMonth[] = ["Jan-26","Feb-26","Mar-26","Apr-26","May-26","Jun-26","Jul-26","Aug-26","Sep-26"];

const P_META: Record<string, [string, string, AccountingCategory, "AVG_BAL_DR_LCY" | "AVG_BAL_CR_LCY" | "NON_FUNDED_LCY" | "REMITTANCE_LCY"]> = {
  LN_DR: ["Corporate Term Loans (LN DR)", "Corporate Term Loans (LN DR)", "asset", "AVG_BAL_DR_LCY"],
  CASA_DR: ["Overdraft & Working Capital (CASA DR)", "Corporate Overdraft & Working Capital (CASA DR)", "asset", "AVG_BAL_DR_LCY"],
  LMS_DR: ["LMS Advances (LMS DR)", "LMS Structured Advances (LMS DR)", "asset", "AVG_BAL_DR_LCY"],
  FB_DR: ["Foreign Bills Purchased & Discounted (FB DR)", "Foreign Bills Purchased & Discounted (FB DR)", "asset", "AVG_BAL_DR_LCY"],
  CARD_DR: ["Credit Cards (CARD DR)", "Commercial & Corporate Credit Cards (CARD DR)", "asset", "AVG_BAL_DR_LCY"],
  CASA_CR: ["Current & Savings Accounts (CASA CR)", "Corporate Current & Call Accounts (CASA CR)", "liability", "AVG_BAL_CR_LCY"],
  TD_CR: ["Term & Fixed Deposits (TD CR)", "Corporate Term & Fixed Deposits (TD CR)", "liability", "AVG_BAL_CR_LCY"],
  FC_MARGIN_CR: ["Foreign Currency Margin Deposits (FC MARGIN CR)", "Foreign Currency Margin Deposits (FC MARGIN CR)", "liability", "AVG_BAL_CR_LCY"],
  CARD_CR: ["Card Credit Balances (CARD CR)", "Commercial Card Credit Balances (CARD CR)", "liability", "AVG_BAL_CR_LCY"],
  LMS_CR: ["LMS Credit Balances (LMS CR)", "LMS Credit Balances (LMS CR)", "lms_cr", "AVG_BAL_CR_LCY"],
  BG_DR: ["Bank Guarantees (BG DR)", "Bank Guarantees & Performance Bonds", "non_funded", "NON_FUNDED_LCY"],
  DOC_CR_DR: ["Documentary Credits / Letters of Credit (DC DR)", "Letters of Credit & Documentary Credits", "non_funded", "NON_FUNDED_LCY"],
  REMIT_DR: ["Remittances (Remittance DR)", "Inward & Outward International Remittances", "remittance", "REMITTANCE_LCY"],
};

function h(code: string, dec25Bf: number, bals: number[], revs: number[] = [0,0,0,0,0,0,0,0,0]): ProductHoldingRow {
  const [productName, productGroup, category, measureLabel] = P_META[code];
  const monthlyBalances = {} as Record<ReportingMonth, number>;
  const monthlyRevenue = {} as Record<ReportingMonth, number>;
  for (let i = 0; i < 9; i++) {
    monthlyBalances[MONTHS[i]] = bals[i] ?? 0;
    monthlyRevenue[MONTHS[i]] = revs[i] ?? 0;
  }
  return { productCode: code, productName, productGroup, category, measureLabel, dec25Bf, monthlyBalances, monthlyRevenue };
}

function dg(f: number, ib: number, mb: number, ndc: number, nde: number): Record<DigitalPlatformId, DigitalStatus> {
  const s = (v: number): DigitalStatus => (v === 1 ? "registered" : v === 0 ? "not_registered" : "not_supplied");
  return { frimi: s(f), internet_banking: s(ib), mobile_banking: s(mb), ndc: s(ndc), nde: s(nde) };
}

function dr(directorCif: string, name: string | null, latestAssetsMn: number | null = null, latestLiabilitiesMn: number | null = null, ytdRevenueMn: number | null = null, reportedLimitMn: number | null = null): DirectorLink {
  return { directorCif, name, role: "Linked Director Relationship", hasBalanceExtract: name !== null, latestAssetsMn, latestLiabilitiesMn, ytdRevenueMn, reportedLimitMn };
}

