function pc(cif: string, legalName: string, shortName: string, entityType: "Corporate" | "Individual", sector: string, subSector: string, website: string, reportedLimitMn: number | null, digital: [number,number,number,number,number], holdings: ProductHoldingRow[], directors: DirectorLink[], parentCompanyCif?: string, parentCompanyName?: string): CustomerRecord {
  return {
    cif,
    isPrimaryCustomer: true,
    ...(parentCompanyCif ? { parentCompanyCif, parentCompanyName } : {}),
    reportedLimitMn,
    company: {
      legalName,
      shortName,
      entityType,
      sector,
      subSector,
      headquarters: "Sri Lanka",
      relationshipTier: entityType === "Individual" ? "Private Wealth" : "Corporate Premier",
      relationshipManager: "",
      branchName: "",
      description: "",
      strategicContext: "",
      keyHighlights: [],
      links: website ? [{ label: "Official Website", url: website, type: "website" }] : [],
      lastVerifiedDate: "2026-11-03",
    },
    digitalAccess: dg(...digital),
    holdings,
    directors,
    savedRecommendations: recs(entityType, digital[4] === 1),
  };
}

function dc(cif: string, name: string, parentCompanyCif: string, parentCompanyName: string, reportedLimitMn: number | null, hasBal: boolean, holdings: ProductHoldingRow[]): CustomerRecord {
  return {
    cif,
    isPrimaryCustomer: false,
    parentCompanyCif,
    parentCompanyName,
    reportedLimitMn,
    company: {
      legalName: name,
      shortName: name,
      entityType: "Individual",
      sector: "Linked Director — Personal Banking",
      subSector: `Linked Director Relationship — ${parentCompanyName}`,
      headquarters: "Sri Lanka",
      relationshipTier: "Private Wealth",
      relationshipManager: "",
      branchName: "",
      description: "",
      strategicContext: "",
      keyHighlights: [],
      links: [],
      lastVerifiedDate: "2026-11-03",
    },
    digitalAccess: hasBal ? dg(-1,1,1,-1,-1) : dg(-1,-1,-1,-1,-1),
    holdings,
    directors: [],
    savedRecommendations: recs("Individual", false),
  };
}

